const https = require("https");
const fs = require("fs");
const path = require("path");

const rc = JSON.parse(fs.readFileSync("/home/loser/.clasprc.json", "utf8"));
const token = rc.tokens.default.access_token;
const scriptId = "1_8MaqmPL9iqbA3ekldVcmu7uU_i7pi5yQigXbF097cNHTR8zL5N2QKcm";

const dir = ".";
const filenames = ["Import.gs", "Menu.gs", "Trigger.gs", "UploadDialog.html", "appsscript.json"];

const files = filenames.map(f => {
  const content = fs.readFileSync(path.join(dir, f), "utf8");
  let name = path.basename(f, path.extname(f));
  let type = "server_js";
  if (f.endsWith(".html")) type = "html";
  if (f.endsWith(".json")) type = "JSON";
  return { name, type, source: content };
});

const postData = JSON.stringify({ files });

const req = https.request({
  hostname: "script.googleapis.com",
  path: `/v1/projects/${scriptId}/content`,
  method: "PUT",
  headers: {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(postData)
  }
}, (res) => {
  let body = "";
  res.on("data", chunk => body += chunk);
  res.on("end", () => console.log("PUSH STATUS:", res.statusCode, body.substring(0, 300)));
});
req.write(postData);
req.end();
'

